  GVTypes[16]=strdup("short");
  GVNames[17]=strdup("maliciousV2XCost");
  GVTypes[17]=strdup("short");
  GVNames[18]=strdup("reflashChipCost");
  GVTypes[18]=strdup("short");
  GVNames[19]=strdup("remoteDataExtractionThreshold");
  GVTypes[19]=strdup("short");
  GVNames[20]=strdup("remoteExtractionCost");
