  hasMessageFormatKnowledgeValues = new bool[NumExps];
  hasProximityNetworkAccessValues = new bool[NumExps];
  hasRemoteNetworkAccessValues = new bool[NumExps];
  hasV2XProtocolKnowledgeValues = new bool[NumExps];
  injectionSkillLevelValues = new short[NumExps];
